//! Actions-only original Buddy check query/codec/ownership and isolation tests.
use super::*;
use n::{buddy_relation_check as check,rpc_im::{ImQuery,ImReplyData},relation_journal::RelationConfiguration,rpc_stream::{CodecError,MAX_STREAM_BYTES}};
fn fixture()->Fixture{let mut f=Fixture::new(true);f.backend.close();let mut b=OfflineBackend::new(f.owner.clone());b.claim_common_transport().unwrap();b.bind_common_identity(b"AccountEntry").unwrap();let cfg=NativeReceiverConfig{direct_domains:None,invite_notifications:None,im_messages:Some(NativeImConfig{notification_timeout_ms:30000,receive_info:false,directory_queries:false})};let p=NativeReceiverPolicy::capture(&cfg).unwrap().with_buddy_relation_check(check::NativeBuddyRelationCheckConfig{check:true}).unwrap();b.arm_native_receivers(NativeReceiverSetup::capture(p,true,None).unwrap()).unwrap();f.scope=b.connection_scope();let p=b.prepare_login(login(),&[]).unwrap();b.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(p.call_id,&login_result()),0).unwrap();b.configure_native_receivers(7).unwrap();f.backend=b;f}
fn prepared(f:&Fixture,uid:&[u8],end:Instant)->(Arc<ImQuery>,check::CheckWait){let input=f.scope.reserve_native_rpc(check::input_size(uid).unwrap()).unwrap();let config=Arc::new(f.temp.database.with_conn(|c|RelationConfiguration::capture(c,f.run.line_id(),f.run.revision(),Some(&f.scope))).unwrap());let c=check::CheckContext::capture(f.temp.database.clone(),f.run.clone(),f.owner.clone(),f.scope.clone(),config,f.gate.clone(),end).unwrap();let q=Arc::new(ImQuery::buddy_check(uid,input,end).unwrap()).bind_buddy_context(c.clone()).unwrap();(q.clone(),check::CheckWait(c,q))}
fn channel_ready(now:Instant)->n::reliable_channel::ChannelCore{use n::native_channel::{self,HeaderMode,PacketKind,ChannelPacket};let mut c=n::reliable_channel::ChannelCore::new(0,1460,now+Duration::from_secs(10),Duration::from_secs(2),now).unwrap();let p=c.next_packet(now).unwrap().unwrap();let s=native_channel::decode_packet(HeaderMode::Basic,p.expose_to_transport()).unwrap();let p=native_channel::encode_packet(HeaderMode::Basic,&ChannelPacket{timestamp:None,sequence:0x9000,kind:PacketKind::Start,data_gap:0,ack_sequence:s.sequence,delivered_sequence:s.sequence,inclusive_ack:false,ack_mask:&[],body:&[]}).unwrap();c.on_packet(p.expose_to_transport(),now).unwrap();assert!(c.ready());c.next_packet(now).unwrap().unwrap();c}
#[test]fn buddy_check_packet_rechecks_shorter_actual_rpc_deadline_after_sql_lock_wait(){
 let mut f=fixture();let original=Instant::now()+Duration::from_secs(30);let(q,_interest)=prepared(&f,b"1_2",original);let short=Instant::now()+Duration::from_millis(100);let p=f.backend.prepare_im_read(q,f.gate.clone(),short).unwrap();let guard=p.packets[0].group_event_retention().unwrap();assert!(guard.current(Instant::now()));let db=f.temp.database.clone();let(tx,rx)=std::sync::mpsc::channel();let(release,wait)=std::sync::mpsc::channel();let blocker=std::thread::spawn(move||db.with_conn(|_|{tx.send(()).unwrap();wait.recv().unwrap();Ok(())}).unwrap());rx.recv().unwrap();let(tx,rx)=std::sync::mpsc::channel();let reading=std::thread::spawn(move||{tx.send(()).unwrap();guard.current(Instant::now())});rx.recv().unwrap();std::thread::sleep(short.saturating_duration_since(Instant::now())+Duration::from_millis(10));release.send(()).unwrap();blocker.join().unwrap();assert!(!reading.join().unwrap());assert!(Instant::now()<original);assert!(f.backend.take_im_replies().is_empty());
}
#[test]fn buddy_check_channel_retry_retains_original_holder_and_wait_drop_blocks_retransmit(){
 let mut f=fixture();let now=Instant::now();let(q,wait)=prepared(&f,b"1_2",now+Duration::from_secs(30));let p=f.backend.prepare_im_read(q.clone(),f.gate.clone(),now+Duration::from_secs(3)).unwrap();let guard=p.packets[0].group_event_retention().unwrap();let mut c=channel_ready(now);c.queue_record_retained(b"original buddy check encoded record",now+Duration::from_secs(3),now,Some(guard)).unwrap();let first=c.next_packet(now).unwrap().unwrap();assert!(first.group_event_packet_current(Instant::now()));let retry=c.next_packet(now+Duration::from_millis(200)).unwrap().unwrap();assert!(retry.group_event_retention().is_some());drop(wait);assert!(!retry.group_event_packet_current(Instant::now()));assert_eq!(c.next_packet(now+Duration::from_millis(400)).err(),Some(n::reliable_channel::ChannelError::Closed));c.close();f.backend.close();drop(p);drop(first);drop(q);assert!(f.scope.native_rpc_resources().1>0);drop(retry);assert_eq!(f.scope.native_rpc_resources(),(0,0));
}
fn body(accepted:bool,ty:u32,reason:&[u8],footer:bool)->Vec<u8>{let mut w=Writer::new();w.boolean(accepted).unwrap();w.u32(ty).unwrap();w.bytes(reason).unwrap();if footer{w.properties(&[RpcProperty{key:b"private",value:b"never-a-grant"}]).unwrap();}w.finish().expose_to_transport().to_vec()}
#[test]fn buddy_check_absence_keeps_private_config_bytes_and_does_not_inherit_directory_or_write(){let cert=n::tls_engine::tests::Certificates::generate("IP:127.0.0.1");let mut c=n::account_config::tests::native_fixture(&cert.root,"127.0.0.1",1);let old=c.encode_private().unwrap();assert!(c.profile.buddy_relation_check.is_none());assert!(!String::from_utf8_lossy(&old).contains("buddy_relation_check"));let copy=n::account_config::AccountConfig::decode_private(&old).unwrap();assert_eq!(copy.encode_private().unwrap(),old);c.profile.buddy_relation_check=Some(check::NativeBuddyRelationCheckConfig{check:true});assert!(c.runtime_profile().is_err());c.profile.incoming=None;c.profile.client_ex=true;c.profile.native_receivers=Some(NativeReceiverConfig{direct_domains:None,invite_notifications:None,im_messages:Some(NativeImConfig{notification_timeout_ms:3000,receive_info:false,directory_queries:false})});assert!(c.runtime_profile().is_ok());assert!(c.profile.relation_updates.is_none()&&c.profile.relation_roster.is_none()&&c.profile.im_user_read.is_none());let raw=c.encode_private().unwrap();assert_eq!(n::account_config::AccountConfig::decode_private(&raw).unwrap().encode_private().unwrap(),raw);}
#[test]fn buddy_check_policy_rejects_false_extra_fields_and_duplicate_installation(){for json in [r#"{"check":false}"#,r#"{"check":true,"write":true}"#,r#"{"check":null}"#,r#"{}"#]{let cfg=serde_json::from_str::<check::NativeBuddyRelationCheckConfig>(json);assert!(cfg.is_err()||cfg.unwrap().validate().is_err());}let cfg=NativeReceiverConfig{direct_domains:None,invite_notifications:None,im_messages:Some(NativeImConfig{notification_timeout_ms:3000,receive_info:false,directory_queries:false})};let p=NativeReceiverPolicy::capture(&cfg).unwrap();assert!(!p.buddy_relation_check());let p=p.with_buddy_relation_check(check::NativeBuddyRelationCheckConfig{check:true}).unwrap();assert!(p.with_buddy_relation_check(check::NativeBuddyRelationCheckConfig{check:true}).is_err());assert!(!p.im_messages().unwrap().directory_queries&&!p.org_relation_sync()&&!p.relation_roster());}
#[test]fn buddy_check_exact_original_method_uid_and_measured_versioned_arguments(){let mut f=fixture();let end=Instant::now()+Duration::from_secs(30);let(q,_wait)=prepared(&f,b"1_2",end);let p=f.backend.prepare_im_read(q.clone(),f.gate.clone(),end).unwrap();assert_eq!(p.call_id,2);let r=decode_request(&p.packets[0].expose_to_transport()[1..]).unwrap();assert_eq!(r.method,b"checkRelation.GroupServer.Group");assert_eq!(r.metadata.len(),2);assert_eq!(r.metadata.iter().find(|p|p.key==b"id").unwrap().value,b"#Group");assert_eq!(r.metadata.iter().find(|p|p.key==b"token").unwrap().value,b"fixture-auth");assert_eq!(r.arguments,[0,0,1,0,0,0,0,0,3,b'1',b'_',b'2']);let b=check::encode(b"1_2").unwrap();assert_eq!(b.allocated_capacity(),12);assert!(!q.directory_query());}
#[test]fn buddy_check_explicit_uid_never_guesses_telephone_group_box_or_uri(){for uid in [b"".as_slice(),b"1_0",b"1-2",b"P2P/1_2",b"+12345",b"[uid:1_2]",b"[phone:+12345@x.invalid]",b" 1_2",b"1_2\0",b"1_2\n"]{assert!(check::encode(uid).is_err());}assert!(check::encode(b"0_1").is_ok());assert!(check::encode(&[b'1';513]).is_err());}
#[test]fn buddy_check_directory_installation_and_missing_context_cannot_authorize_request(){let mut f=Fixture::with_directory(true,false,true);let end=Instant::now()+Duration::from_secs(30);let(q,_wait)=prepared(&f,b"1_2",end);assert!(f.backend.prepare_im_read(q,f.gate.clone(),end).is_err());let p=f.backend.prepare_im_read(Arc::new(ImQuery::relations(None,-1).unwrap()),f.gate.clone(),end).unwrap();assert_eq!(p.call_id,2);let mut f=fixture();let input=f.scope.reserve_native_rpc(check::input_size(b"1_2").unwrap()).unwrap();let q=Arc::new(ImQuery::buddy_check(b"1_2",input,end).unwrap());assert!(f.backend.prepare_im_read(q,f.gate.clone(),end).is_err());}
#[test]fn buddy_check_false_reason_and_all_u32_types_remain_data_not_authority(){for(accepted,ty,reason)in[(true,0,b"".as_slice()),(true,u32::MAX,b"".as_slice()),(false,12,b"".as_slice()),(true,20,b"refused".as_slice())]{let mut f=fixture();let end=Instant::now()+Duration::from_secs(30);let(q,_wait)=prepared(&f,b"1_2",end);let p=f.backend.prepare_im_read(q.clone(),f.gate.clone(),end).unwrap();f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(p.call_id,&body(accepted,ty,reason,true)),0).unwrap();let r=f.backend.take_im_replies().pop().unwrap();assert!(Arc::ptr_eq(r.request().query_arc(),&q));assert_eq!(r.request().deadline(),end);let ImReplyData::BuddyCheck(v)=r.result().unwrap()else{panic!("check result")};assert_eq!(v.accepted,accepted&&reason.is_empty());assert_eq!(v.relation_type,ty);assert_eq!(v.footer.properties.len(),1);assert_eq!(f.count(),0);assert!(f.temp.database.get_recent_app_events(Some(f.run.line_id()),10).unwrap().is_empty());assert!(f.temp.database.with_conn(|c|n::relation_journal::history(c,f.run.line_id(),128)).unwrap().is_empty());assert!(n::im_inbox::CursorSession::from_refresh(f.run.clone(),f.gate.clone(),&r).is_err());}}
#[test]fn buddy_check_result_truncation_trailing_duplicate_and_nonzero_code_reject_with_original_nonzero_bool(){let f=fixture();let bytes=body(true,0xf1234567,b"",true);let no_footer=body(true,0xf1234567,b"",false);for end in 0..bytes.len(){assert_eq!(check::decode(&f.scope,0,&bytes[..end]).is_ok(),end==no_footer.len());}let mut b=bytes.clone();b.push(0);assert!(check::decode(&f.scope,0,&b).is_err());for code in [1,65536,65537,u32::MAX]{assert!(check::decode(&f.scope,code,&bytes).is_err());}let mut b=no_footer.clone();b[1]=2;assert!(check::decode(&f.scope,0,&b).unwrap().accepted);let mut w=Writer::new();w.boolean(true).unwrap();w.u32(1).unwrap();w.bytes(b"").unwrap();w.u32(2).unwrap();for _ in 0..2{w.bytes(b"same").unwrap();w.bytes(b"").unwrap();}assert!(check::decode(&f.scope,0,w.finish().expose_to_transport()).is_err());assert_eq!(f.scope.native_rpc_resources(),(0,0));}
#[test]fn buddy_check_retired_or_foreign_context_does_not_allocate_id_or_revive_current_scope(){for mode in 0..3{let mut f=fixture();let other=fixture();let end=Instant::now()+Duration::from_secs(30);let(q,wait)=prepared(if mode==0{&other}else{&f},b"1_2",end);if mode==1{drop(wait);}if mode==2{f.gate.retire();}assert!(f.backend.prepare_im_read(q,f.gate.clone(),end).is_err());assert!(f.backend.take_im_replies().is_empty());assert!(f.scope.is_open());}}
#[test]fn buddy_check_same_revision_configuration_change_retires_packet_and_reply_without_sql_mutation(){let mut f=fixture();let end=Instant::now()+Duration::from_secs(30);let(q,_wait)=prepared(&f,b"1_2",end);let p=f.backend.prepare_im_read(q,f.gate.clone(),end).unwrap();let held=p.packets[0].group_event_retention().unwrap();assert!(held.current(Instant::now()));f.temp.database.with_conn(|c|c.execute("UPDATE app_voice_accounts SET private_config=X'00'",[]).map_err(|_|"fixture")).unwrap();assert!(!held.current(Instant::now()));assert!(f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(p.call_id,&body(true,12,b"",false)),0).unwrap().is_empty());assert!(f.backend.take_im_replies().is_empty());assert!(f.scope.is_open());assert!(f.temp.database.get_recent_app_events(Some(f.run.line_id()),128).unwrap().is_empty());assert_eq!(f.count(),0);}
#[test]fn buddy_check_detached_packet_retains_original_request_budget_after_close_until_last_drop(){let mut f=fixture();let end=Instant::now()+Duration::from_secs(30);let(q,wait)=prepared(&f,b"1_2",end);let p=f.backend.prepare_im_read(q.clone(),f.gate.clone(),end).unwrap();let guard=p.packets[0].group_event_retention().unwrap();let charged=f.scope.native_rpc_resources();assert!(charged.0>=3);let packet=p.packets.into_iter().next().unwrap();f.backend.close();drop(q);drop(wait);assert_eq!(f.scope.native_rpc_resources(),charged);assert!(!guard.current(Instant::now()));drop(guard);assert_eq!(f.scope.native_rpc_resources(),charged);drop(packet);assert_eq!(f.scope.native_rpc_resources(),(0,0));}
#[test]fn buddy_check_scratch_and_request_use_original_128kib_budget_and_release_on_error(){let f=fixture();let wire=body(true,1,b"",true);let size=check::decode_size(0,&wire).unwrap();let full=f.scope.reserve_native_rpc(MAX_STREAM_BYTES-size+1).unwrap();assert_eq!(check::decode(&f.scope,0,&wire).err(),Some(CodecError::TooLarge));drop(full);let result=check::decode(&f.scope,0,&wire).unwrap();assert_eq!(f.scope.native_rpc_resources(),(1,size));f.scope.close();assert_eq!(f.scope.native_rpc_resources(),(1,size));drop(result);assert_eq!(f.scope.native_rpc_resources(),(0,0));}
#[test]fn buddy_check_wrong_rpc_or_owner_is_not_current_result_and_never_replays(){let mut f=fixture();let other=fixture();let end=Instant::now()+Duration::from_secs(30);let(q,_wait)=prepared(&f,b"1_2",end);let p=f.backend.prepare_im_read(q,f.gate.clone(),end).unwrap();let b=body(true,12,b"",false);f.backend.on_plaintext_packet(&other.owner,&f.scope,&reply_packet(p.call_id,&b),0).unwrap();f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(p.call_id+1,&b),0).unwrap();assert!(f.backend.take_im_replies().is_empty());f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(p.call_id,&b),0).unwrap();assert_eq!(f.backend.take_im_replies().len(),1);f.backend.on_plaintext_packet(&f.owner,&f.scope,&reply_packet(p.call_id,&b),0).unwrap();assert!(f.backend.take_im_replies().is_empty());}
